    "kelas": "Kelas 4",
    "mapelKode": "MTK",
    "judulBab": "Bab 3: Pola Gambar dan Pola Bilangan",
    "judulModul": "Modul Ajar Matematika - Pola Gambar dan Pola Bilangan (Sesuai Buku Paket)",
