    "saranaPrasarana": "Buku Siswa Matematika Kelas IV Penerbit Kemendikbudristek, kelereng, kartu bergambar pola (segitiga, lingkaran), korek api kayu, LKPD kelompok.",
    "targetPeserta": "Siswa Reguler (Umum)",
