    "tujuanPembelajaranText": "1. Peserta didik dapat mengidentifikasi pola gambar membesar dan mengecil yang melibatkan penjumlahan dan pengurangan bilangan cacah.\n2. Peserta didik dapat mengembangkan dan membuat pola gambar membesar dan mengecil.\n3. Peserta didik dapat mengidentifikasi pola bilangan membesar dan mengecil.\n4. Peserta didik dapat memprediksi suku atau pola bilangan berikutnya berdasarkan keteraturan yang ada.",
    "pemahamanBermakna": "Mengetahui konsep pola membantu kita dalam memprediksi kejadian di masa depan, menyusun desain seni dekoratif, memahami urutan baris antrean, dan memprogram algoritma logika sederhana.",
    "pertanyaanPemantik": "1. Jika baris pertama ada 2 kelereng, baris kedua ada 4 kelereng, dan baris ketiga ada 6 kelereng, berapa banyak kelereng di baris kelima?\n2. Bagaimana kalian tahu bahwa setelah angka 5, 8, 11, angka berikutnya adalah 14? Aturan apa yang digunakan?",
    "kegiatanPendahuluan": "Pertemuan 1 (2 JP - 70 Menit)\n1. Orientasi (10 Menit):\n- Guru mengucapkan salam, menanyakan kabar siswa, berdoa bersama dipimpin salah satu murid, dan memeriksa kehadiran.\n2. Apersepsi (5 Menit):\n- Guru menyusun beberapa spidol di meja: 1 spidol hitam, 2 spidol biru, 3 spidol merah. Guru bertanya: 'Jika bapak ingin melanjutkan susunan ini, berapa spidol warna hijau yang harus ditaruh?'\n3. Motivasi (5 Menit):\n- Guru menceritakan pentingnya pola di dunia nyata, seperti pola sarang lebah atau susunan ubin lantai.\n4. Pemberian Acuan (5 Menit):\n- Guru menyampaikan tujuan pembelajaran hari ini yaitu mengidentifikasi pola gambar membesar dan mengecil.",
    "kegiatanInti": "Pertemuan 1 (2 JP - 70 Menit)\n1. Orientasi Siswa pada Masalah (15 Menit):\n- Guru menampilkan gambar pola susunan korek api membentuk segitiga berurutan di papan tulis.\n- Guru membagikan korek api ke setiap kelompok.\n2. Mengorganisasikan Siswa (10 Menit):\n- Siswa berkumpul dalam kelompok diskusi (4-5 orang) dan menerima LKPD Bab 3.\n3. Membimbing Penyelidikan (15 Menit):\n- Siswa meniru susunan korek api (Susunan 1: 3 batang, Susunan 2: 5 batang, Susunan 3: 7 batang).\n- Siswa menghitung selisih pertambahan batang korek api antar susunan. Guru memberikan bimbingan bagi kelompok yang kesulitan mendeteksi beda selisih.\n4. Mengembangkan Hasil Karya (15 Menit):\n- Perwakilan kelompok merakit pola di depan kelas menggunakan batang korek api raksasa / gambar magnetik di papan tulis.\n5. Analisis & Evaluasi (15 Menit):\n- Guru memberikan evaluasi terhadap jalannya presentasi kelompok dan menyimpulkan konsep pola membesar (+2 batang).",
    "kegiatanPenutup": "Pertemuan 1 (15 Menit)\n1. Simpulan (5 Menit):\n- Siswa dibantu guru menyimpulkan aturan pola gambar membesar dan mengecil.\n2. Refleksi (5 Menit):\n- Guru menanyakan: 'Bagian mana dari pelajaran hari ini yang paling kalian sukai?'\n3. Tindak Lanjut (5 Menit):\n- Guru memberikan pekerjaan rumah (PR) dari Buku Siswa Matematika Kelas IV halaman 45, lalu ditutup dengan doa bersama.",
    "asesmenDiagnostik": "Tes lisan menebak bilangan loncat sederhana, misalnya 2, 4, 6, ..., 10 sebelum KBM dimulai.",
    "asesmenFormatif": "Penilaian proses unjuk kerja kelompok dalam memanipulasi batang korek api dan ketepatan laporan LKPD kelompok.",
    "asesmenSumatif": "Tes esai tertulis mandiri berupa 5 soal menentukan gambar/angka kelanjutan pola bilangan membesar dan mengecil.",
    "lkpd": "LEMBAR KERJA PESERTA DIDIK (LKPD) KELOMPOK\nMata Pelajaran: Matematika\nMateri: Pola Batang Korek Api\n\nNama Anggota Kelompok:\n1. .....................\n2. .....................\n3. .....................\n4. .....................\n\nLangkah Kerja:\n1. Susunlah batang korek api membentuk pola berikut:\n   - Susunan 1: Segitiga tunggal (membutuhkan 3 batang)\n   - Susunan 2: Dua segitiga berhimpit (membutuhkan 5 batang)\n   - Susunan 3: Tiga segitiga berhimpit (membutuhkan 7 batang)\n2. Hitunglah berapa banyak batang korek api yang dibutuhkan untuk Susunan 4?\n3. Tuliskan pola bilangan yang terbentuk dari banyak batang korek api tersebut!\n4. Apa aturan pola bilangan tersebut? (Ditambah/dikurangi berapa?)",
    "glosarium": "1. Pola: Bentuk atau urutan teratur yang tetap.\n2. Pola Membesar: Pola yang nilainya bertambah banyak.\n3. Pola Mengecil: Pola yang nilainya berkurang/sedikit.",
    "daftarPustaka": "1. Hobri, dkk. 2022. Buku Panduan Guru Matematika untuk SD Kelas IV. Jakarta: Pusat Perbukuan Kemendikbudristek.\n2. Hobri, dkk. 2022. Buku Siswa Matematika untuk SD Kelas IV. Jakarta: Pusat Perbukuan Kemendikbudristek."
